        , cast(null as varchar) as DIAGNOSTIC_CENTRE_REMARKS
        , cast(null as varchar) as PRESCRIPTION_SUBMITTED_INDICATOR
        , 'BJAZ_EC_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ec_mem_dtls_extn') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MEMBER_NO))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as MEMBER_REFERENCE
        , cast(null as varchar) as CONDITION_CODE
        , cast(null as varchar) as GESTATION_MONTHS
        , cast(null as varchar) as FAMILY_MEDICAL_HISTORY_DETAIL
        , cast(null as varchar) as ILLNESS_DURATION
        , cast(null as varchar) as TREATMENT_DESCRIPTION
        , DECEASE_TREATMENT_DTLS as TREATMENT_DETAILS_NARRATIVE
        , cast(null as varchar) as DECLARED_INSURANCE_PERIOD
        , cast(null as varchar) as TREATMENT_PERIOD
        , cast(null as varchar) as TREATING_DOCTOR_NAME
        , cast(null as varchar) as DECLARED_HEALTH_REMARKS
        , cast(null as varchar) as PRESCRIPTION_DETAIL
        , cast(null as varchar) as DIAGNOSTIC_CENTRE_REMARKS
        , cast(null as varchar) as PRESCRIPTION_SUBMITTED_INDICATOR
        , 'BJAZ_HCF_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcf_member_dtls') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__CONTRACT_ID_MEMBER_ID))) as HUB_RISK_OBJECT_HK
        , coalesce(nullif(trim(MEMBER_ID), ''), '') as MEMBER_REFERENCE
        , 'DECLARED_OTHER' as CONDITION_CODE
        , cast(null as varchar) as GESTATION_MONTHS
        , cast(null as varchar) as FAMILY_MEDICAL_HISTORY_DETAIL
        , cast(null as varchar) as ILLNESS_DURATION
        , cast(null as varchar) as TREATMENT_DESCRIPTION
        , cast(null as varchar) as TREATMENT_DETAILS_NARRATIVE
        , SH_PERIOD_OF_INSURANCE as DECLARED_INSURANCE_PERIOD
        , SH_PERIOD_TREATMENT as TREATMENT_PERIOD
        , SH_DOCTOR_NAME as TREATING_DOCTOR_NAME
        , SH_COMMENTS as DECLARED_HEALTH_REMARKS
        , HC_PRESCRIPTION_DETAILS as PRESCRIPTION_DETAIL
        , REMARK_CENTER as DIAGNOSTIC_CENTRE_REMARKS
        , HC_PRESCRIPTION_YN as PRESCRIPTION_SUBMITTED_INDICATOR
        , 'BJAZ_HM_MEMBER_HLTH_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_hlth_dtls') }}
