        MEMBER_REFERENCE,
        CONDITION_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GESTATION_MONTHS end) as GESTATION_MONTHS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FAMILY_MEDICAL_HISTORY_DETAIL end) as FAMILY_MEDICAL_HISTORY_DETAIL,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ILLNESS_DURATION end) as ILLNESS_DURATION,
