        max(case when SOURCE_RUN = 'opus_health_v2' then DIAGNOSTIC_CENTRE_REMARKS end) as DIAGNOSTIC_CENTRE_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_v2' then PRESCRIPTION_SUBMITTED_INDICATOR end) as PRESCRIPTION_SUBMITTED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
