                     then md5(upper(coalesce(cast(MEMBER_REFERENCE as varchar), '') || '|' || coalesce(cast(CONDITION_CODE as varchar), '') || '|' || coalesce(cast(GESTATION_MONTHS as varchar), '') || '|' || coalesce(cast(FAMILY_MEDICAL_HISTORY_DETAIL as varchar), '') || '|' || coalesce(cast(ILLNESS_DURATION as varchar), '') || '|' || coalesce(cast(TREATMENT_DESCRIPTION as varchar), '') || '|' || coalesce(cast(TREATMENT_DETAILS_NARRATIVE as varchar), '') || '|' || coalesce(cast(DECLARED_INSURANCE_PERIOD as varchar), '') || '|' || coalesce(cast(TREATMENT_PERIOD as varchar), '') || '|' || coalesce(cast(TREATING_DOCTOR_NAME as varchar), '') || '|' || coalesce(cast(DECLARED_HEALTH_REMARKS as varchar), '') || '|' || coalesce(cast(PRESCRIPTION_DETAIL as varchar), '') || '|' || coalesce(cast(DIAGNOSTIC_CENTRE_REMARKS as varchar), '') || '|' || coalesce(cast(PRESCRIPTION_SUBMITTED_INDICATOR as varchar), '')))
                end as SAT_RISK_HEALTH_MEMBER_MEDICAL_HASHDIFF
    from resolved
